retry.interval:
@{
                var r = context.Response;
                int attempt = context.Variables.GetValueOrDefault<int>("attemptCount", 1);

                // 1) Honor server provided timing (clamped to a sane 1..60s window).
                if (r != null)
                {
                    var raMs = r.Headers.GetValueOrDefault("retry-after-ms", "");
                    if (!string.IsNullOrEmpty(raMs) && int.TryParse(raMs, out var ms))
                        return Math.Max(1, Math.Min((int)Math.Ceiling(ms / 1000.0), 60));

                    var raS = r.Headers.GetValueOrDefault("retry-after", "");
                    if (!string.IsNullOrEmpty(raS) && int.TryParse(raS, out var s))
                        return Math.Max(1, Math.Min(s, 60));
                }

                // 2) Decorrelated jitter exponential backoff: base 1s, cap 30s.
                //    exponent = retries already done = attemptCount - 1.
                var rnd = new Random(Guid.NewGuid().GetHashCode());
                int expo = (int)Math.Min(30.0, Math.Pow(2, Math.Max(0, attempt - 1)));
                return Math.Max(1, rnd.Next(1, expo + 1));
            }

retry.condition:
@{
                var r = context.Response;
                if (r == null) return false;               // transport errors go to on-error
                int sc = r.StatusCode;

                // 429 is retriable EXCEPT subscription quota exhaustion (terminal).
                if (sc == 429)
                {
                    var body = r.Body?.As<string>(preserveContent: true) ?? string.Empty;
                    return !(body.Contains("QuotaExceeded") || body.Contains("insufficient_quota"));
                }

                // Always retriable transient / gateway codes.
                if (sc == 408 || sc == 500 || sc == 502 || sc == 503 || sc == 504)
                    return true;

                // 404 retriable ONLY for a just created deployment (DeploymentNotFound).
                if (sc == 404)
                {
                    var body = r.Body?.As<string>(preserveContent: true) ?? string.Empty;
                    return body.Contains("DeploymentNotFound");
                }

                return false;
            }
